1	import { describe, it, expect } from 'vitest';
2	import { readFileSync } from 'fs';
3	import { join } from 'path';
4	
5	/**
6	 * Auth Route Guard Test Suite
7	 *
8	 * Tests for auth-route-guard.md specifications:
9	 * - #{#ath1a} Layout-level auth guard
10	 * - #{#ath1b} Not-logged-in message display
11	 * - #{#ath1c} Remove per-page auth redirects
12	 *
13	 * These are source-code pattern tests that verify the layout and pages
14	 * contain the expected auth guard patterns.
15	 */
16	
17	const layoutPath = join(process.cwd(), 'src/routes/+layout.svelte');
18	
19	describe('Auth Route Guard', () => {
20		describe('#{#ath1a} Layout-Level Auth Guard', () => {
21			it('should track auth loading state', () => {
22				const content = readFileSync(layoutPath, 'utf-8');
23	
24				// Layout must have a loading state variable for auth
25				const hasAuthLoading = content.includes('authLoading') || content.includes('authChecked');
26	
27				expect(hasAuthLoading).toBe(true);
28			});
29	
30			it('should define public routes that do not require auth', () => {
31				const content = readFileSync(layoutPath, 'utf-8');
32	
33				// Layout must define which routes are public
34				const hasPublicRoutes =
35					content.includes('/login') &&
36					content.includes('/forgot-password') &&
37					content.includes('/reset-password');
38	
39				expect(hasPublicRoutes).toBe(true);
40			});
41	
42			it('should gate page content based on auth state for protected routes', () => {
43				const content = readFileSync(layoutPath, 'utf-8');
44	
45				// Layout must conditionally render children based on auth
46				// Either checking session or a derived auth state
47				const gatesContent =
48					(content.includes('isPublicRoute') || content.includes('publicRoutes')) &&
49					content.includes('{@render children()}');
50	
51				expect(gatesContent).toBe(true);
52			});
53	
54			it('should hide nav links when user is not authenticated', () => {
55				const content = readFileSync(layoutPath, 'utf-8');
56	
57				// Nav links to protected pages should be inside a session check
58				// The nav section with receipts/transactions/etc should be conditional
59				const hasConditionalNav =
60					content.includes('$session') &&
61					content.includes('/receipts') &&
62					// Nav links should be inside an {#if $session} block
63					(content.includes('{#if $session}') || content.includes('{#if session}'));
64	
65				expect(hasConditionalNav).toBe(true);
66			});
67		});
68	
69		describe('#{#ath1b} Not-Logged-In Message Display', () => {
70			it('should display a not-logged-in message for unauthenticated users', () => {
71				const content = readFileSync(layoutPath, 'utf-8');
72	
73				// Must show some form of "not logged in" messaging
74				const hasNotLoggedInMessage =
75					content.includes('not logged in') ||
76					content.includes('Not logged in') ||
77					content.includes('not signed in') ||
78					content.includes('Not signed in') ||
79					content.includes('sign in') ||
80					content.includes('log in to continue');
81	
82				expect(hasNotLoggedInMessage).toBe(true);
83			});
84	
85			it('should include a link or button to the login page', () => {
86				const content = readFileSync(layoutPath, 'utf-8');
87	
88				// Must have a login link/button in the not-logged-in state
89				const hasLoginLink = content.includes('href="/login"') || content.includes("goto('/login')");
90	
91				expect(hasLoginLink).toBe(true);
92			});
93		});
94	
95		describe('#{#ath1c} Remove Per-Page Auth Redirects', () => {
96			const protectedPages = [
97				{ name: 'receipts', path: join(process.cwd(), 'src/routes/receipts/+page.svelte') },
98				{ name: 'transactions', path: join(process.cwd(), 'src/routes/transactions/+page.svelte') },
99				{ name: 'expenses', path: join(process.cwd(), 'src/routes/expenses/+page.svelte') },
100				{
101					name: 'reconciliation',
102					path: join(process.cwd(), 'src/routes/reconciliation/+page.svelte')
103				}
104			];
105	
106			for (const page of protectedPages) {
107				it(`should not have auth redirect in ${page.name} page`, () => {
108					const content = readFileSync(page.path, 'utf-8');
109	
110					// Pages should NOT contain window.location.href = '/login' redirect
111					const hasAuthRedirect =
112						content.includes("window.location.href = '/login'") ||
113						content.includes('window.location.href = "/login"');
114	
115					expect(hasAuthRedirect).toBe(false);
116				});
117			}
118		});
119	});
