12	
13	// Mock supabase client
14	vi.mock('$lib/supabaseClient', () => ({
15		supabase: {
16			auth: {
17				getUser: vi.fn()
18			},
19			from: vi.fn()
20		}
21	}));
22	
23	/** Typed replacement for `supabase.auth.getUser` mock results (module-mocked vi.fn). */
24	type GetUserResult = Awaited<ReturnType<typeof supabase.auth.getUser>>;
25	type QueryBuilder = ReturnType<typeof supabase.from>;
26	
27	describe('ReceiptService - Bulk Operations', () => {
28		let service: ReceiptService;
29		let mockDelete: ReturnType<typeof vi.fn>;
30		let mockIn: ReturnType<typeof vi.fn>;
31		let mockEq: ReturnType<typeof vi.fn>;
32	
33		beforeEach(() => {
34			service = new ReceiptService(supabase);
35	
36			// Reset mocks
37			vi.clearAllMocks();
38	
39			// Setup mock chain
40			mockDelete = vi.fn();
41			mockIn = vi.fn();
42			mockEq = vi.fn();
43	
44			// Default successful response
45			mockEq.mockResolvedValue({ data: null, error: null });
46			mockIn.mockReturnValue({ eq: mockEq });
47			mockDelete.mockReturnValue({ in: mockIn });
48	
49			vi.mocked(supabase.from).mockReturnValue({ delete: mockDelete } as unknown as QueryBuilder);
50			vi.mocked(supabase.auth.getUser).mockResolvedValue({
51				data: { user: { id: 'test-user-id' } }
52			} as unknown as GetUserResult);
53		});
54	
55		describe('#{#blk3a} Bulk Delete Database Operation', () => {
56			it('should have a bulkDeleteReceipts method', () => {
57				// This test will fail until the method is implemented
58				expect(service.bulkDeleteReceipts).toBeDefined();
59				expect(typeof service.bulkDeleteReceipts).toBe('function');
60			});
61	
62			it('should delete multiple receipts in a single database query', async () => {
63				const receiptIds = ['id-1', 'id-2', 'id-3'];
64	
65				await service.bulkDeleteReceipts(receiptIds);
66	
67				// Verify single query was made
68				expect(supabase.from).toHaveBeenCalledTimes(1);
69				expect(supabase.from).toHaveBeenCalledWith('receipts');
70				expect(mockDelete).toHaveBeenCalledTimes(1);
