129			it('should provide specific error messages for network errors', async () => {
130				const receiptIds = ['id-1', 'id-2'];
131	
132				mockEq.mockResolvedValue({
133					data: null,
134					error: { message: 'Network error', code: 'NETWORK_ERROR' }
135				});
136	
137				try {
138					await service.bulkDeleteReceipts(receiptIds);
