145			it('should provide specific error messages for permission errors', async () => {
146				const receiptIds = ['id-1', 'id-2'];
147	
148				mockEq.mockResolvedValue({
149					data: null,
150					error: { message: 'Permission denied', code: 'PERMISSION_DENIED' }
151				});
152	
153				try {
154					await service.bulkDeleteReceipts(receiptIds);
155					expect.fail('Should have thrown error');
156				} catch (error) {
157					expect((error as Error).message).toBeTruthy();
