160	
161			it('should not attempt to delete storage files in bulk delete', async () => {
162				// Bulk delete should be database-only for performance
163				// Storage cleanup can happen via database triggers or separate process
164				const receiptIds = ['id-1', 'id-2', 'id-3'];
165	
166				await service.bulkDeleteReceipts(receiptIds);
167	
168				// Verify only database delete was called, no storage operations
