1	import { describe, it, expect } from 'vitest';
2	import {
3		applySelectionClick,
4		emptySelection,
5		isAllSelected,
6		isIndeterminate,
7		toggleSelectAll,
8		type SelectionState
9	} from './selectionModel';
10	
11	/**
12	 * Pure multi-select state machine shared by the list-page tables (RF-03).
13	 *
14	 * Modifier semantics (clicks land on the row checkbox; plain row-click is edit):
15	 *  - plain          → toggle the row, set anchor
16	 *  - Cmd/Ctrl       → additive toggle, set anchor
17	 *  - Shift          → union the anchor→row range in the current visible order
18	 *
19	 * Tested through the public interface only (ordered ids + state + click → state),
20	 * so no browser and no component are needed to pin the correctness-critical logic.
21	 */
22	const empty: SelectionState = { selected: new Set<string>(), anchorId: null };
23	const plain = { shiftKey: false, toggleKey: false };
24	const shift = { shiftKey: true, toggleKey: false };
25	const toggle = { shiftKey: false, toggleKey: true };
26	
27	describe('selectionModel', () => {
28		it('plain click selects a previously unselected row and anchors it', () => {
29			const next = applySelectionClick(['a', 'b', 'c'], empty, 'b', plain);
30	
31			expect([...next.selected]).toEqual(['b']);
32			expect(next.anchorId).toBe('b');
33		});
34	
35		it('plain click deselects an already-selected row and re-anchors it', () => {
36			const state: SelectionState = { selected: new Set(['a', 'b']), anchorId: 'a' };
37	
38			const next = applySelectionClick(['a', 'b', 'c'], state, 'b', plain);
39	
40			expect([...next.selected]).toEqual(['a']);
41			expect(next.anchorId).toBe('b');
42		});
43	
44		it('Shift+click unions the anchor→row range in visible order and keeps the anchor', () => {
45			const state: SelectionState = { selected: new Set(['b']), anchorId: 'b' };
46	
47			const next = applySelectionClick(['a', 'b', 'c', 'd', 'e'], state, 'd', shift);
48	
49			expect([...next.selected].sort()).toEqual(['b', 'c', 'd']);
50			expect(next.anchorId).toBe('b');
51		});
52	
53		it('Shift+click extends the range when the target is above the anchor', () => {
54			const state: SelectionState = { selected: new Set(['d']), anchorId: 'd' };
55	
56			const next = applySelectionClick(['a', 'b', 'c', 'd', 'e'], state, 'b', shift);
57	
58			expect([...next.selected].sort()).toEqual(['b', 'c', 'd']);
59			expect(next.anchorId).toBe('d');
60		});
61	
62		it('Shift range follows the current visible order, not the original order', () => {
63			// Rows re-sorted so the visible order is reversed; range must use it.
64			const state: SelectionState = { selected: new Set(['e']), anchorId: 'e' };
65	
66			const next = applySelectionClick(['e', 'd', 'c', 'b', 'a'], state, 'c', shift);
67	
68			expect([...next.selected].sort()).toEqual(['c', 'd', 'e']);
69		});
70	
71		it('Shift+click degrades to a plain toggle when there is no anchor', () => {
72			const next = applySelectionClick(['a', 'b', 'c'], empty, 'b', shift);
73	
74			expect([...next.selected]).toEqual(['b']);
75			expect(next.anchorId).toBe('b');
76		});
77	
78		it('Shift+click degrades to a plain toggle when the anchor is no longer visible', () => {
79			// Anchor 'x' was filtered out of the current rows.
80			const state: SelectionState = { selected: new Set(['a']), anchorId: 'x' };
81	
82			const next = applySelectionClick(['a', 'b', 'c'], state, 'c', shift);
83	
84			expect([...next.selected].sort()).toEqual(['a', 'c']);
85			expect(next.anchorId).toBe('c');
86		});
87	
88		it('Cmd/Ctrl+click additively toggles without clearing other rows', () => {
89			const state: SelectionState = { selected: new Set(['a', 'c']), anchorId: 'a' };
90	
91			const next = applySelectionClick(['a', 'b', 'c'], state, 'b', toggle);
92	
93			expect([...next.selected].sort()).toEqual(['a', 'b', 'c']);
94			expect(next.anchorId).toBe('b');
95		});
96	});
97	
98	describe('emptySelection', () => {
99		it('has nothing selected and no anchor', () => {
100			const state = emptySelection();
101	
102			expect(state.selected.size).toBe(0);
103			expect(state.anchorId).toBeNull();
104		});
105	});
106	
107	describe('selectionModel header state', () => {
108		it('isAllSelected is true only when every visible row is selected', () => {
109			expect(isAllSelected(['a', 'b'], new Set(['a', 'b']))).toBe(true);
110			expect(isAllSelected(['a', 'b'], new Set(['a']))).toBe(false);
111		});
112	
113		it('isAllSelected is false for an empty list (nothing to select)', () => {
114			expect(isAllSelected([], new Set())).toBe(false);
115		});
116	
117		it('isAllSelected ignores selected ids that are not currently visible', () => {
118			// 'x' was filtered out; both visible rows are selected, so header is "all".
119			expect(isAllSelected(['a', 'b'], new Set(['a', 'b', 'x']))).toBe(true);
120		});
121	
122		it('isIndeterminate is true when some but not all visible rows are selected', () => {
123			expect(isIndeterminate(['a', 'b', 'c'], new Set(['b']))).toBe(true);
124			expect(isIndeterminate(['a', 'b'], new Set())).toBe(false);
125			expect(isIndeterminate(['a', 'b'], new Set(['a', 'b']))).toBe(false);
126		});
127	
128		it('toggleSelectAll selects every visible row when not all are selected', () => {
129			const next = toggleSelectAll(['a', 'b', 'c'], { selected: new Set(['a']), anchorId: 'a' });
130	
131			expect([...next.selected].sort()).toEqual(['a', 'b', 'c']);
132		});
133	
134		it('toggleSelectAll clears the visible rows when all are already selected', () => {
135			const next = toggleSelectAll(['a', 'b'], { selected: new Set(['a', 'b']), anchorId: 'b' });
136	
137			expect([...next.selected]).toEqual([]);
138		});
139	
140		it('toggleSelectAll preserves selected rows that are not currently visible', () => {
141			// 'x' is filtered out; selecting all visible must not drop it.
142			const next = toggleSelectAll(['a', 'b'], { selected: new Set(['x']), anchorId: null });
143	
144			expect([...next.selected].sort()).toEqual(['a', 'b', 'x']);
145		});
146	});
