1	/**
2	 * Test Suite for Email Attachment Filtering
3	 *
4	 * Tests for:
5	 * - #{#eaf1a} Filter attachments by supported MIME types
6	 * - #{#eaf2a} Skip inline attachments
7	 * - #{#eaf3a} Validate OCR results before receipt insert
8	 * - #{#eaf4a} Process all valid attachments (structural — tested via integration assertions)
9	 * - #{#eaf5a} Prioritize attachments over email body text
10	 *
11	 * Authority: system (eaf1a-eaf3a), developer (eaf4a-eaf5a)
12	 * Priority: Critical / High
13	 */
14	
15	import { describe, it, expect } from 'vitest';
16	import {
