1	/**
2	 * Tests for inbound sender-email parsing.
3	 *
4	 * Regression coverage for "User not found for sender email": the webhook must
5	 * look up the user by the bare address, not the raw `from` header. A forwarded
6	 * receipt whose `from` includes a display name (`Name <addr>`) previously failed
7	 * the exact-match lookup even for registered users.
8	 */
9	
10	import { describe, it, expect } from 'vitest';
11	import { parseSenderEmail } from './emailParsing.ts';
12	
13	describe('parseSenderEmail', () => {
14		it('returns a bare address unchanged (lowercased)', () => {
15			expect(parseSenderEmail('mark@agilepainrelief.com')).toBe('mark@agilepainrelief.com');
16		});
17	
18		it('extracts the address from display-name form', () => {
19			expect(parseSenderEmail('Mark Levison <mark@agilepainrelief.com>')).toBe(
20				'mark@agilepainrelief.com'
21			);
22		});
23	
24		it('extracts the address from a quoted display name containing a comma', () => {
25			expect(parseSenderEmail('"Levison, Mark" <mark@agilepainrelief.com>')).toBe(
26				'mark@agilepainrelief.com'
27			);
28		});
29	
30		it('lowercases the extracted address so it matches the case-insensitive RPC', () => {
31			expect(parseSenderEmail('Mark <MARK@Example.COM>')).toBe('mark@example.com');
32			expect(parseSenderEmail('DORIS@YOURFINANCIALLAUNCHPAD.COM')).toBe(
33				'doris@yourfinanciallaunchpad.com'
34			);
35		});
36	
37		it('trims surrounding whitespace', () => {
38			expect(parseSenderEmail('   a@b.com   ')).toBe('a@b.com');
39			expect(parseSenderEmail('  Name <a@b.com>  ')).toBe('a@b.com');
40		});
41	
42		it('uses the final angle-bracket group when the display name has stray brackets', () => {
43			expect(parseSenderEmail('"<vip> Name" <real@domain.com>')).toBe('real@domain.com');
44		});
45	
46		it('returns null for empty / missing input', () => {
47			expect(parseSenderEmail(null)).toBeNull();
48			expect(parseSenderEmail(undefined)).toBeNull();
49			expect(parseSenderEmail('')).toBeNull();
50			expect(parseSenderEmail('   ')).toBeNull();
51		});
52	
53		it('returns null when no usable address can be extracted', () => {
54			expect(parseSenderEmail('Just A Name')).toBeNull();
55			expect(parseSenderEmail('not-an-email')).toBeNull();
56			expect(parseSenderEmail('a@b')).toBeNull(); // no dotted domain
57			expect(parseSenderEmail('Name <still not an email>')).toBeNull();
58		});
59	});
