19	
20		import { onMount } from 'svelte';
21		import { DEFAULT_CATEGORY_COLOR, type Category } from '$lib/types/Category';
22		import { supabase } from '$lib/supabaseClient';
23		import { ExpenseService } from '$lib/services/ExpenseService';
