33			onCreateNewCategory?: (data: { name: string; color: string | null }) => void;
34			onVendorRuleCreated?: (data: { merchantName: string; categoryId: string }) => void;
35		}
36	
37		let {
38			currentCategory = null,
39			categories = [],
40			onCategorySelect = () => {},
41			familyId = '',
42			merchantName = '',
43			onCategorySelected,
44			onCreateNewCategory,
45			onVendorRuleCreated
46		}: Props = $props();
47	
48		// Component state
49		let isOpen = $state(false);
50		let searchQuery = $state('');
51		let selectedIndex = $state(0);
52		let dropdownElement: HTMLDivElement;
53		let searchInputElement = $state<HTMLInputElement>();
54	
55		// #{#exp3b} Inline creation state
56		let isInCreationMode = $state(false);
57		let newCategoryName = $state('');
58		let newCategoryColor = $state('');
59		let creationError: string | null = $state(null);
60		let nameInputElement = $state<HTMLInputElement>();
61	
62		// Vendor rule state
63		let vendorRule: { category_id: string; category_name: string } | null = $state(null);
64		let loadingVendorRule = $state(false);
65	
66		// Computed: Filter categories based on search query
67		let filteredCategories = $derived(filterCategories(categories, searchQuery));
68	
69		/**
70		 * Filter categories by search query (case-insensitive partial match)
71		 * #{#exp2a} Criterion 4
72		 */
73		function filterCategories(cats: Category[], query: string): Category[] {
74			if (!query || query.trim() === '') {
75				return cats;
76			}
77			const normalizedQuery = query.toLowerCase();
78			return cats.filter((cat) => cat.name.toLowerCase().includes(normalizedQuery));
79		}
80	
81		/**
82		 * Open dropdown and focus search input
83		 * #{#exp2a} Criterion 2, 3
84		 */
85		async function openDropdown() {
86			isOpen = true;
87			searchQuery = '';
88			selectedIndex = 0;
89	
90			// Load vendor rule if merchant info is available
91			if (merchantName && familyId) {
92				loadingVendorRule = true;
93				try {
