110		/**
111		 * Close dropdown and reset state
112		 * #{#exp2a} Criterion 9
113		 */
114		function closeDropdown() {
115			isOpen = false;
116			searchQuery = '';
117			selectedIndex = 0;
118		}
119	
120		/**
121		 * Toggle dropdown open/close
122		 * #{#exp2a} Criterion 2
123		 */
