149			const maxIndex = filteredCategories.length - 1;
150	
151			switch (event.key) {
152				case 'ArrowDown':
153					event.preventDefault();
154					selectedIndex = selectedIndex < maxIndex ? selectedIndex + 1 : selectedIndex;
155					break;
156	
157				case 'ArrowUp':
158					event.preventDefault();
159					selectedIndex = selectedIndex > 0 ? selectedIndex - 1 : selectedIndex;
160					break;
161	
162				case 'Enter':
163					event.preventDefault();
164					if (filteredCategories.length > 0 && selectedIndex >= 0) {
165						selectCategory(filteredCategories[selectedIndex]);
166					}
167					break;
168	
169				case 'Escape':
170					event.preventDefault();
171					closeDropdown();
172					break;
173			}
174		}
