287		/**
288		 * Set vendor default category rule
289		 * #{#exp5a} - Vendor Rule Management
290		 */
291		async function handleSetVendorDefault() {
292			if (!familyId || !merchantName || !currentCategory) return;
293	
294			try {
295				const expenseService = new ExpenseService(supabase);
296				await expenseService.createVendorRule(familyId, merchantName, currentCategory.id);
